mapper.select:
SELECT

FROM
    dm_change_flow_item
WHERE
    owner_uid    = #{ownerUid}
    AND
    ref_flow_id  = #{flowId}
    AND
    content_name = #{contentName}
LIMIT 1

mapper.delete:
DELETE FROM
    dm_change_flow_item
WHERE
    owner_uid   = #{ownerUid}
    AND
    ref_flow_id = #{flowId}
